def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.198.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.197.0"' not in init:
        sys.exit("ABORT: not at v3.197.0.")
    if "rfq_quotes" not in data:
        sys.exit("ABORT: rfq_quotes module not found in data file.")

    problems = _validate("PROC4", LESSONS_P4, QUESTIONS_P4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P4))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC4 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P4)
    print(f"PROC 4 v3: {len(LESSONS_P4)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P4):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["rfq_quotes"]["lessons"] = LESSONS_P4
    data["rfq_quotes"]["questions"] = bank
    data["rfq_quotes"]["desc"] = ("Requests for Quotation and the comparison cycle in ZhiftERP: when the policy requires competitive quotes and the named recorded exceptions; the Request for Quotation walk — supplier selection, consolidated quantities, the complete message, and the managed response window; Supplier Quotation entry from attached documents with the pairing rule, tiered breaks, and foreign-currency handling; the comparison worksheet with the landed centre column and the stated criteria; the award decision — best total position, split awards, the decision minute with alternatives, and the updates to lists, orders, and supplier files; negotiation from the recorded position, volume bands, standing arrangements with real validity, and the owned re-quote calendar; and the five cycle reads including the quarterly savings record.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.197.0"', '"3.198.0"'))
    print("  data: PROCUREMENT 4 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.198.0")


if __name__ == "__main__":
    main()
